/* Chart.js-compatible tiny line chart renderer for the offline bundle. */
(function(global){
  function num(v){ const n=Number(v); return Number.isFinite(n)?n:null; }
  class Chart{
    constructor(ctx, config){ this.ctx=ctx; this.config=config||{}; this.data=this.config.data||{labels:[],datasets:[]}; this.options=this.config.options||{}; this.draw(); }
    update(){ this.draw(); }
    destroy(){ const c=this.ctx.canvas; this.ctx.clearRect(0,0,c.width,c.height); }
    draw(){
      const ctx=this.ctx, canvas=ctx.canvas, dpr=global.devicePixelRatio||1; const rect=canvas.getBoundingClientRect ? canvas.getBoundingClientRect() : {width:canvas.width||800,height:canvas.height||350};
      const w=Math.max(300,rect.width||800), h=Math.max(220,rect.height||350); if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){ canvas.width=Math.round(w*dpr); canvas.height=Math.round(h*dpr); }
      ctx.setTransform(dpr,0,0,dpr,0,0); ctx.clearRect(0,0,w,h); ctx.font='12px system-ui, sans-serif'; ctx.lineWidth=1;
      const labels=this.data.labels||[]; const sets=this.data.datasets||[]; const values=[]; sets.forEach(s=>(s.data||[]).forEach(v=>{v=num(v); if(v!=null) values.push(v);}));
      if(!labels.length||!values.length){ ctx.fillText('No data',20,30); return; }
      const pad={l:54,r:20,t:36,b:42}; const x0=pad.l,y0=h-pad.b,x1=w-pad.r,y1=pad.t; const minY=this.options?.scales?.y?.min ?? Math.floor(Math.min(...values)-1); const maxY=Math.ceil(Math.max(...values)+1); const minX=0, maxX=labels.length-1 || 1;
      ctx.strokeStyle='#d6d6d6'; ctx.fillStyle='#555'; ctx.beginPath(); ctx.moveTo(x0,y1); ctx.lineTo(x0,y0); ctx.lineTo(x1,y0); ctx.stroke();
      for(let i=0;i<=5;i++){ const y=y0-(y0-y1)*i/5; const val=minY+(maxY-minY)*i/5; ctx.strokeStyle='#ececec'; ctx.beginPath(); ctx.moveTo(x0,y); ctx.lineTo(x1,y); ctx.stroke(); ctx.fillStyle='#555'; ctx.fillText(val.toFixed(1),8,y+4); }
      const ticks=8; for(let i=0;i<=ticks;i++){ const x=x0+(x1-x0)*i/ticks; const idx=Math.round(minX+(maxX-minX)*i/ticks); ctx.fillStyle='#555'; ctx.fillText(String(labels[idx]??''),x-10,y0+18); }
      ctx.textAlign='center'; ctx.fillStyle='#333'; ctx.fillText(this.options?.scales?.x?.title?.text||'',(x0+x1)/2,h-8); ctx.save(); ctx.translate(14,(y0+y1)/2); ctx.rotate(-Math.PI/2); ctx.fillText(this.options?.scales?.y?.title?.text||'',0,0); ctx.restore(); ctx.textAlign='left';
      let lx=x0, ly=14; sets.forEach((s,si)=>{ ctx.strokeStyle=s.borderColor||['#ef4444','#4f74ff','#10b981'][si%3]; ctx.fillStyle=ctx.strokeStyle; ctx.fillRect(lx,ly-8,18,3); ctx.fillText(s.label||('Series '+(si+1)),lx+24,ly-4); lx+=120; });
      sets.forEach((s,si)=>{ const arr=s.data||[]; ctx.strokeStyle=s.borderColor||['#ef4444','#4f74ff','#10b981'][si%3]; ctx.lineWidth=s.borderWidth||2; ctx.beginPath(); let started=false; for(let i=0;i<arr.length;i++){ const v=num(arr[i]); if(v==null) continue; const x=x0+(x1-x0)*(i-minX)/(maxX-minX); const y=y0-(y0-y1)*(v-minY)/(maxY-minY || 1); if(!started){ctx.moveTo(x,y); started=true;} else ctx.lineTo(x,y); } ctx.stroke(); });
    }
  }
  global.Chart=Chart;
})(typeof window!=='undefined'?window:globalThis);
